<?php get_header(); ?>
<main id="contenido"><?php while(have_posts()):the_post();$term=mee_article_term();$demo=get_post_meta(get_the_ID(),'_mee_demo',true);$area=get_post_meta(get_the_ID(),'_mee_area',true);$topic=get_post_meta(get_the_ID(),'_mee_topic',true); ?>
<nav class="breadcrumbs" aria-label="Ruta de navegación"><ol><li><a href="https://moevec.org/">Inicio</a></li><li><a href="<?php echo esc_url(home_url('/')); ?>">Editorial</a></li><?php if($term): ?><li><a href="<?php echo esc_url(get_category_link($term)); ?>"><?php echo esc_html($term->name); ?></a></li><?php endif; ?></ol></nav>
