<?php if($area): ?><section class="mee-article-next"><p>Esta idea forma parte de un mapa más grande.</p><a href="https://moevec.org/areas/<?php echo esc_attr($area); ?>/#<?php echo esc_attr($topic); ?>">Volver a su área <span aria-hidden="true">↗</span></a></section><?php echo do_shortcode('[mee_conversacion area="'.esc_attr($area).'"]');endif; ?>
<section class="mee-related"><h2>Seguir conectando ideas.</h2><div><?php $related=new WP_Query(['post_type'=>'post','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'cat'=>$term?$term->parent:0]);while($related->have_posts()):$related->the_post(); ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail('mee-card',['loading'=>'lazy']); ?><h3><?php the_title(); ?></h3></a><?php endwhile;wp_reset_postdata(); ?></div></section>
</article><?php endwhile; ?></main><?php get_footer(); ?>
